WITH prev_events AS (SELECT *, LAG(started_at) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC) AS prev_started_at FROM sessions), gaps AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), sessionized AS (SELECT id, customer_id, device, started_at, country, SUM(is_new_burst) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT session_no, DATE_TRUNC('WEEK', started_at) AS week_start, ROUND(SUM(session_no) / NULLIF(COUNT(CASE WHEN device = 'tablet' THEN 1 END), 0), 2) AS session_no_per_tablet, MAX(started_at) AS last_started_at, SUM(CASE WHEN device = 'desktop' THEN session_no ELSE 0 END) AS desktop_session_no, PERCENT_RANK() OVER (PARTITION BY session_no ORDER BY ROUND(SUM(session_no) / NULLIF(COUNT(CASE WHEN device = 'tablet' THEN 1 END), 0), 2) DESC) AS session_no_per_tablet_percent_rank FROM sessionized GROUP BY session_no, DATE_TRUNC('WEEK', started_at)
